namespace GraphPathFindingDemo.Core.Layout;

/// <summary>
/// Identifies the kind of layout a <see cref="ILayoutGenerator"/> produces.
/// </summary>
public enum LayoutStyle
{
    /// <summary>
    /// Boxes joined by single openings, generated by splitting the grid recursively.
    /// </summary>
    RecursiveDivision,

    /// <summary>
    /// Corridors carved by a depth-first walk that backtracks when it runs out of room.
    /// </summary>
    RecursiveBacktracker,

    /// <summary>
    /// A blobby tree, grown outwards from a single cell by taking the passages that leave the
    /// region at random.
    /// </summary>
    RandomizedPrim,

    /// <summary>
    /// A tree built row by row, joining the cells of a row into groups that carry at least one
    /// passage into the next row.
    /// </summary>
    Eller,

    /// <summary>
    /// A tree built by walking at random from every cell until the walk reaches the maze.
    /// </summary>
    Wilson,

    /// <summary>
    /// A tree grown outwards from the whole set of cells reached so far.
    /// </summary>
    GrowingTree,

    /// <summary>
    /// A tree built by walking at random through the cells that are left, and hunting for a place
    /// to carry on when the walk runs into a dead end.
    /// </summary>
    HuntAndKill,

    /// <summary>
    /// A maze with loops, made by knocking the walls out of the dead ends of a perfect maze.
    /// </summary>
    Braided,

    /// <summary>
    /// A maze with loops, made by knocking out many of the walls a perfect maze does not need.
    /// </summary>
    SparseWalls,

    /// <summary>
    /// A maze with loops, made by knocking out few of the walls a perfect maze does not need.
    /// </summary>
    DenseWalls,

    /// <summary>
    /// A maze of rectangular rooms joined by doors.
    /// </summary>
    RoomAndCorridor,

    /// <summary>
    /// A maze of caves, made by letting a cellular automaton settle the walls.
    /// </summary>
    CellularAutomataCaves,

    /// <summary>
    /// A grid of separate groves, each of them a maze of its own.
    /// </summary>
    Forest,

    /// <summary>
    /// A perfect maze built by Kruskal's algorithm, taking the cheapest passages first.
    /// </summary>
    WeightedKruskal
}
